    P = json.loads('\x7b"texts": \x7b"today_word": "today", "on_date": "on [date]", "question": "Can you pay [amount] [when]?", "question_product": "For your [words], can you pay [amount] [when]?", "question_all": "Can you pay all of them today?", "weekend_or_holiday": "[named] is not a business day, so I cannot record it. The next business day is [date].", "after_deadline": "The latest date I can record is [deadline].", "before_today": "[named] has already passed.", "below_floor": "I cannot record [named]. The lowest amount I can record is [floor], your [floor_name].", "above_full": "Your past-due amount is [full], so that is the most I can record.", "vague": "Which exact day would that be?", "vague_deadline": "The latest date I can record is [deadline].", "too_much_floor": "I understand. The lowest amount I can accept is [floor], your [floor_name]. The rest stays overdue.", "exhausted": "I understand.", "one_by_one": "Let us go through them one by one.", "next_product": "Your [words] has [past_due] past due.", "paid": "Thank you for letting me know. Payments can take one business day to appear, so I will not take a promise for your [words].", "dispute": "Thank you for telling me. I will not take a promise for your [words].", "hardship": "I am sorry to hear that. Would you like me to connect you with our customer support team?", "human_first": "I can help you with most things myself. Is there anything I can help you with before I transfer you?", "notalk_first": "I understand. This will only take a moment.", "readback_head": "To confirm: your ", "readback_item": "[words], [amount], [when]", "readback_sep": "; ", "own_deadline": ", which is the latest date I can record for it", "moved_bd": ", the next business day", "readback_tail": ". Do you confirm?", "recorded": "Your promise is recorded.", "recorded_many": "Your promises for [list] are recorded.", "rec_failed": "I could not record the promise for your [words] because of a technical problem.", "anything_else": "Is there anything else I can help you with?", "wrap_change": "A recorded promise cannot be changed or cancelled on this call, but you can change it in the Freya Bank mobile app.", "and": " and ", "after_recorded": "You will receive a text message confirming this promise."\x7d, "multi": false, "notes": false, "note_reasons": \x7b\x7d, "fin_keys": \x7b"promise": "promise", "paid": "paid", "default": "refused", "refused": "refused", "hardship": "hardship", "dispute": "dispute", "service_error": "service_error"\x7d, "asides": \x7b"robot": \x7b"when": "asks whether they are talking to a robot, a machine or an AI", "say": "I am Freya Bank\'s digital assistant."\x7d, "scam": \x7b"when": "asks whether this call is a scam or genuine", "say": "You can verify this call by phoning Freya Bank\'s customer service number."\x7d\x7d, "weekday_rule": "this_week", "fail_max": 2, "max_checks": 8, "human_limit": 2, "notalk_limit": 2, "wrap_turns": 2, "closed_day_move": "after", "ordinals": ["first", "second", "third"], "clear_enums": ["stance", "offer_kind", "offer_for", "topic", "confirm", "hs_answer", "wrap", "aside"], "clear_values": ["offer_date", "offer_amount", "offer_when"], "outcome_var": "outcome", "reason_var": "reason", "promise_outcome": "promise", "now_var": "now", "after_recorded": true\x7d')
    def g(V, k, d=''):
