    def init_negotiation(V, statement):
        ids = pids(V)
        V['mode'] = 'negotiate'
        V['stage'] = 'all' if multi(V) else 'one'
        V['cur_pid'] = ids[0] if ids else ''
        V['human_count'] = '0'
        V['notalk_count'] = '0'
        V['wrap_count'] = '0'
        V['wrap_human'] = '0'
        V['vague_all'] = 'no'
        V['hs_offer'] = 'no'
        if ids:
