            for p in opn:
                pset(V, p, 'state', 'hardship')
            opn = []
        if opn:
            start_product(V, opn[0], prefix)
            return
        agreed = [p for p in ids if state(V, p) == 'agreed']
        if agreed:
            V['readback_line'] = join([prefix, readback(V, agreed)])
            V['route'] = 'confirm'
            return
