            pset(V, pid, 'state', 'hardship')
            advance(V, '')
            return
        a0, d0 = prop_of(V, pid)
        rl = refused_list(V, pid)
        if okey(a0, d0) not in rl:
            rl.append(okey(a0, d0))
        pset(V, pid, 'refused_offers', ';'.join(rl))
        L = ladder(V, pid)
        k = int(num(pg(V, pid, 'attempts_used'), 0) or 0)
        while k < len(L):
