            head = ('Product ' + str(i + 1) + ' of ' + str(len(ids)) + ': ') if len(ids) > 1 else 'Product: '
            s = head + pg(V, p, 'words') + ' (id ' + p + '). Past due ' + fmt(full_of(V, p)) + ', lowest amount ' + fmt(floor_of(V, p)) + ', latest date ' + txt_short(deadline_of(V, p)) + '.'
